import React, { useState, useRef } from 'react'
import { useAuth } from '../contexts/AuthContext'
import { supabase } from '../lib/supabase'
import { Camera, Loader, X } from 'lucide-react'

export default function ProfilePicture({ size = 'lg', editable = false, onUpdate }) {
    const { user, profile, updateAvatar } = useAuth()
    const [uploading, setUploading] = useState(false)
    const [preview, setPreview] = useState(null)
    const fileInputRef = useRef(null)

    const avatarUrl = profile?.avatar_url || null
    const initials = profile?.username?.[0]?.toUpperCase() || user?.email?.[0]?.toUpperCase() || 'U'

    const sizeClasses = {
        sm: 'w-8 h-8 text-xs',
        md: 'w-10 h-10 text-sm',
        lg: 'w-16 h-16 text-xl',
        xl: 'w-20 h-20 text-2xl',
        xxl: 'w-32 h-32 text-4xl'
    }

    const sizeClass = sizeClasses[size] || sizeClasses.lg

    const handleFileSelect = async (e) => {
        const file = e.target.files[0]
        if (!file) return

        // Validate file type
        if (!file.type.startsWith('image/')) {
            alert('Please select an image file')
            return
        }

        // Validate file size (max 5MB)
        if (file.size > 5 * 1024 * 1024) {
            alert('Image must be less than 5MB')
            return
        }

        // Show preview
        const reader = new FileReader()
        reader.onload = () => setPreview(reader.result)
        reader.readAsDataURL(file)

        await uploadAvatar(file)
    }

    const uploadAvatar = async (file) => {
        setUploading(true)
        try {
            const fileExt = file.name.split('.').pop()
            const fileName = `${user.id}-${Date.now()}.${fileExt}`
            const filePath = `avatars/${fileName}`

            // Upload to Supabase Storage
            const { error: uploadError } = await supabase.storage
                .from('avatars')
                .upload(filePath, file, {
                    cacheControl: '3600',
                    upsert: true
                })

            if (uploadError) throw uploadError

            // Get public URL
            const { data: urlData } = supabase.storage
                .from('avatars')
                .getPublicUrl(filePath)

            const publicUrl = urlData.publicUrl

            // Update profile with new avatar URL
            await updateAvatar(publicUrl)

            setPreview(null)
            if (onUpdate) onUpdate()

        } catch (error) {
            console.error('Error uploading avatar:', error)
            alert('Failed to upload image. Please try again.')
        } finally {
            setUploading(false)
        }
    }

    const triggerFileInput = () => {
        if (editable && !uploading) {
            fileInputRef.current?.click()
        }
    }

    return (
        <div className="relative inline-block">
            {/* Avatar */}
            <div 
                className={`${sizeClass} rounded-full bg-gray-200 flex items-center justify-center overflow-hidden border-2 border-gray-300 relative ${editable ? 'cursor-pointer hover:ring-2 hover:ring-gray-400 transition' : ''}`}
                onClick={triggerFileInput}
            >
                {avatarUrl ? (
                    <img 
                        src={avatarUrl} 
                        alt="Profile" 
                        className="w-full h-full object-cover"
                    />
                ) : preview ? (
                    <img 
                        src={preview} 
                        alt="Preview" 
                        className="w-full h-full object-cover"
                    />
                ) : (
                    <span className="font-bold text-gray-600">{initials}</span>
                )}

                {uploading && (
                    <div className="absolute inset-0 bg-black/50 flex items-center justify-center">
                        <Loader className="w-6 h-6 text-white animate-spin" />
                    </div>
                )}
            </div>

            {/* Camera Icon (editable) */}
            {editable && !uploading && (
                <button
                    onClick={triggerFileInput}
                    className="absolute -bottom-1 -right-1 bg-green-600 text-white rounded-full p-1.5 shadow-lg hover:bg-green-700 transition"
                    title="Change profile picture"
                >
                    <Camera size={14} />
                </button>
            )}

            {/* Hidden file input */}
            <input
                ref={fileInputRef}
                type="file"
                accept="image/*"
                onChange={handleFileSelect}
                className="hidden"
            />
        </div>
    )
}
